SELECT c.comment_id, c.post_id, c.parent_id, c.writer_id AS memberId, m.nickname AS writerNickname, CASE WHEN c.deleted_at IS NOT NULL THEN '삭제된 댓글입니다.' ELSE c.content END AS content, c.created_at, c.updated_at, CASE WHEN c.deleted_at IS NOT NULL THEN TRUE ELSE FALSE END AS deleted FROM comment c JOIN members m ON m.member_id = c.writer_id WHERE c.post_id = #{postId} AND c.parent_id IN
#{parentId}
ORDER BY c.created_at ASC, c.comment_id ASC

